#!/usr/bin/env python3
"""Generate the embedded primer and agent copies from shuttle/primer.md."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
primer = (ROOT / "shuttle/primer.md").read_text()
(ROOT / "shuttle/primer.py").write_text(
    '"""Generated by python3 scripts/sync-primer.py; do not edit."""\n\nPRIMER = '
    + repr(primer) + '\n'
)
(ROOT / "docs/agent-primer.md").write_text(primer)
skill = ROOT / "skills/shuttle/SKILL.md"
skill.parent.mkdir(parents=True, exist_ok=True)
skill.write_text(
    '---\nname: shuttle\ndescription: Orient agents to signed workflows and local run state.\n---\n\n'
    '<!-- BEGIN shuttle prime -->\n' + primer + '<!-- END shuttle prime -->\n'
)
